    // Pendulum model/measurement for Section 4 (EKF vs UKF): state [theta, omega], NONLINEAR dynamics
    // theta'=theta+omega*dt, omega'=omega-(g/L)sin(theta)*dt; NONLINEAR measurement h=sin(theta). Same
    // dynamics as KalmanTests.double.cs's own pendulum fixture, redeclared here (a separate assembly).
    public struct PendulumModelDouble : IdoubleKFModel
    {
        public double dt;
        public double gOverL;

        public void F(in doubleN x, in doubleN u, ref doubleN xNext)
        {
            double th = x[0], om = x[1];
            xNext[0] = th + om * dt;
            xNext[1] = om - gOverL * math.sin(th) * dt;
        }

        public void JacobianF(in doubleN x, in doubleN u, ref doubleMxN J)
        {
            double th = x[0];
            J[0, 0] = (double)1; J[0, 1] = dt;
            J[1, 0] = -gOverL * math.cos(th) * dt; J[1, 1] = (double)1;
        }
    }

    public struct PendulumMeasDouble : IdoubleKFMeasurement
    {
        public void H(in doubleN x, ref doubleN z) => z[0] = math.sin(x[0]);

        public void JacobianH(in doubleN x, ref doubleMxN J)
        {
            J[0, 0] = math.cos(x[0]); J[0, 1] = (double)0;
        }
    }

    // Synthetic drone-scale nonlinear model for Section 4's n=12 row: a ring of n coupled damped
    // oscillators, xNext[i] = a*x[i] + b*sin(x[(i+1)%n]) -- smooth, and contractive REGARDLESS of state
    // magnitude (sin is bounded in [-1,1], so |a|<1 alone bounds every orbit), unlike the pendulum's
    // forward-Euler drift. Exists only to exercise ekfPredict/ukfPredict's Jacobian/sigma-point cost at
    // n=12, not to model any real system.
    public struct RingModelDouble : IdoubleKFModel
    {
        public int n;
        public double a;
        public double b;

        public void F(in doubleN x, in doubleN u, ref doubleN xNext)
        {
            for (int i = 0; i < n; i++)
            {
                int j = (i + 1) % n;
                xNext[i] = a * x[i] + b * math.sin(x[j]);
            }
        }

        public void JacobianF(in doubleN x, in doubleN u, ref doubleMxN J)
        {
            for (int i = 0; i < n; i++)
                for (int k = 0; k < n; k++)
                    J[i, k] = (double)0;
            for (int i = 0; i < n; i++)
            {
                int j = (i + 1) % n;
                J[i, i] += a;
                J[i, j] += b * math.cos(x[j]);
            }
        }
    }

    // Measurement for RingModelDouble: picks m components evenly spread through the ring
    // (indices 0, stride, 2*stride, ...) through sin(), so the Jacobian stays a simple diagonal-in-
    // the-picked-columns pattern regardless of m/n.
    public struct RingMeasDouble : IdoubleKFMeasurement
    {
        public int m;
        public int stride;

        public void H(in doubleN x, ref doubleN z)
        {
            for (int j = 0; j < m; j++) z[j] = math.sin(x[j * stride]);
        }

        public void JacobianH(in doubleN x, ref doubleMxN J)
        {
            int n = J.N_Cols;
            for (int i = 0; i < m; i++)
                for (int k = 0; k < n; k++)
                    J[i, k] = (double)0;
            for (int j = 0; j < m; j++)
                J[j, j * stride] = math.cos(x[j * stride]);
        }
    }

